288→// ensureMetadataBranch creates the orphan entire/checkpoints/v1 branch if it doesn't exist.
289→// If the remote-tracking branch (origin/entire/checkpoints/v1) exists, creates the local
290→// branch from it to preserve existing checkpoint data. Otherwise creates an empty orphan.
291→func EnsureMetadataBranch(repo *git.Repository) error {
292→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
293→
294→	// Check if local branch already exists
295→	_, err := repo.Reference(refName, true)
296→	if err == nil {
297→		// Branch already exists
298→		return nil
299→	}
300→
301→	// Check if remote-tracking branch exists (e.g., after clone)
302→	remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
303→	remoteRef, remoteErr := repo.Reference(remoteRefName, true)
304→	if remoteErr == nil {
305→		// Remote branch exists — create local branch pointing to the same commit
306→		ref := plumbing.NewHashReference(refName, remoteRef.Hash())
307→		if err := repo.Storer.SetReference(ref); err != nil {
308→			return fmt.Errorf("failed to create metadata branch from remote: %w", err)
309→		}
310→		fmt.Fprintf(os.Stderr, "✓ Created local branch '%s' from origin\n", paths.MetadataBranchName)
311→		return nil
312→	}
313→
314→	// No local or remote branch — create empty orphan
315→	emptyTree := &object.Tree{Entries: []object.TreeEntry{}}
316→	obj := repo.Storer.NewEncodedObject()
317→	if err := emptyTree.Encode(obj); err != nil {
318→		return fmt.Errorf("failed to encode empty tree: %w", err)
319→	}
320→	emptyTreeHash, err := repo.Storer.SetEncodedObject(obj)
321→	if err != nil {
322→		return fmt.Errorf("failed to store empty tree: %w", err)
323→	}
324→
325→	// Create orphan commit (no parent)
326→	now := time.Now()
327→	authorName, authorEmail := GetGitAuthorFromRepo(repo)
328→	sig := object.Signature{
329→		Name:  authorName,
330→		Email: authorEmail,
331→		When:  now,
332→	}
333→
334→	commit := &object.Commit{
335→		TreeHash:  emptyTreeHash,
336→		Author:    sig,
337→		Committer: sig,
338→		Message:   "Initialize metadata branch\n\nThis branch stores session metadata.\n",
339→	}
340→	// Note: No ParentHashes - this is an orphan commit
341→
342→	commitObj := repo.Storer.NewEncodedObject()
343→	if err := commit.Encode(commitObj); err != nil {
344→		return fmt.Errorf("failed to encode orphan commit: %w", err)
345→	}
346→	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
347→	if err != nil {
348→		return fmt.Errorf("failed to store orphan commit: %w", err)
349→	}
350→
351→	// Create branch reference
352→	ref := plumbing.NewHashReference(refName, commitHash)
353→	if err := repo.Storer.SetReference(ref); err != nil {
354→		return fmt.Errorf("failed to create metadata branch: %w", err)
355→	}
356→
357→	fmt.Fprintf(os.Stderr, "✓ Created orphan branch '%s' for session metadata\n", paths.MetadataBranchName)
358→	return nil
359→}

