 856→func TestGetGitAuthorFromRepo(t *testing.T) {
 857→	// Cannot use t.Parallel() because subtests use t.Setenv to isolate global git config.
 858→
 859→	tests := []struct {
 860→		name        string
 861→		localName   string
 862→		localEmail  string
 863→		globalName  string
 864→		globalEmail string
 865→		wantName    string
 866→		wantEmail   string
 867→	}{
 868→		{
 869→			name:       "both set locally",
 870→			localName:  "Local User",
 871→			localEmail: "local@example.com",
 872→			wantName:   "Local User",
 873→			wantEmail:  "local@example.com",
 874→		},
 875→		{
 876→			name:        "only name set locally falls back to global for email",
 877→			localName:   "Local User",
 878→			globalEmail: "global@example.com",
 879→			wantName:    "Local User",
 880→			wantEmail:   "global@example.com",
 881→		},
 882→		{
 883→			name:       "only email set locally falls back to global for name",
 884→			localEmail: "local@example.com",
 885→			globalName: "Global User",
 886→			wantName:   "Global User",
 887→			wantEmail:  "local@example.com",
 888→		},
 889→		{
 890→			name:        "nothing set locally falls back to global for both",
 891→			globalName:  "Global User",
 892→			globalEmail: "global@example.com",
 893→			wantName:    "Global User",
 894→			wantEmail:   "global@example.com",
 895→		},
 896→		{
 897→			name:      "nothing set anywhere returns defaults",
 898→			wantName:  "Unknown",
 899→			wantEmail: "unknown@local",
 900→		},
 901→		{
 902→			name:        "local takes precedence over global",
 903→			localName:   "Local User",
 904→			localEmail:  "local@example.com",
 905→			globalName:  "Global User",
 906→			globalEmail: "global@example.com",
 907→			wantName:    "Local User",
 908→			wantEmail:   "local@example.com",
 909→		},
 910→	}
 911→
 912→	for _, tt := range tests {
 913→		t.Run(tt.name, func(t *testing.T) {
 914→			// Isolate global git config by pointing HOME to a temp dir
 915→			home := t.TempDir()
 916→			t.Setenv("HOME", home)
 917→			t.Setenv("XDG_CONFIG_HOME", "")
 918→
 919→			// Write global .gitconfig if needed
 920→			if tt.globalName != "" || tt.globalEmail != "" {
 921→				globalCfg := "[user]\n"
 922→				if tt.globalName != "" {
 923→					globalCfg += "\tname = " + tt.globalName + "\n"
 924→				}
 925→				if tt.globalEmail != "" {
 926→					globalCfg += "\temail = " + tt.globalEmail + "\n"
 927→				}
 928→				if err := os.WriteFile(filepath.Join(home, ".gitconfig"), []byte(globalCfg), 0o644); err != nil {
 929→					t.Fatalf("failed to write global gitconfig: %v", err)
 930→				}
 931→			}
 932→
 933→			// Create a repo for config resolution
 934→			dir := t.TempDir()
 935→			repo, err := git.PlainInit(dir, false)
 936→			if err != nil {
 937→				t.Fatalf("failed to init repo: %v", err)
 938→			}
 939→
 940→			// Set local config if needed
 941→			if tt.localName != "" || tt.localEmail != "" {
 942→				cfg, err := repo.Config()
 943→				if err != nil {
 944→					t.Fatalf("failed to get repo config: %v", err)
 945→				}
 946→				cfg.User.Name = tt.localName
 947→				cfg.User.Email = tt.localEmail
 948→				if err := repo.SetConfig(cfg); err != nil {
 949→					t.Fatalf("failed to set repo config: %v", err)
 950→				}
 951→			}
 952→
 953→			gotName, gotEmail := GetGitAuthorFromRepo(repo)
 954→			if gotName != tt.wantName {
 955→				t.Errorf("name = %q, want %q", gotName, tt.wantName)
 956→			}
 957→			if gotEmail != tt.wantEmail {
 958→				t.Errorf("email = %q, want %q", gotEmail, tt.wantEmail)
 959→			}
 960→		})
 961→	}
 962→}
